const channelKey = $('Вход от диспетчера').first().json.channelKey;
const match = items.find(i => String(i.json.tmpl_Channel || '').trim() === channelKey);

if (!match) {
  throw new Error('Шаблон для канала ' + channelKey + ' не найден в Templates');
}

return [{ json: match.json }];

function stripLabel(key) {
  return key.replace(/^[^a-zA-Z]+/, '');
}

// Вытаскивает из общей ячейки SystemPrompt только раздел нужного этапа,
// помеченный маркерами ###ТЕГ### ... ###/ТЕГ###. Так один и тот же столбец
// служит и Художнику, и Писателю, и Технической части без перекрёстного
// загрязнения ролей.
function extractSection(text, tag) {
  if (!text) return '';
  const re = new RegExp('###' + tag + '###([\\s\\S]*?)###/' + tag + '###');
  const m = text.match(re);
  return m ? m[1].trim() : '';
}

// Собирает текст ВСЕХ колонок, отмеченных любым из значков — сколько бы
// их ни было и как бы они ни назывались. Новую колонку с тем же значком
// добавили в таблицу — она сама сюда попадёт, без правки этого кода.
// SystemPrompt сюда не попадает — у него отдельная, посекционная обработка ниже.
function collectByIcons(tmpl, icons) {
  const parts = [];
  for (const key of Object.keys(tmpl)) {
    if (key.includes('tmpl_SystemPrompt')) continue;
    if (icons.some(icon => key.includes(icon))) {
      const value = tmpl[key];
      if (value) parts.push(stripLabel(key) + ':\n' + value);
    }
  }
  return parts.join('\n\n');
}

// Google Drive отдаёт HTML-страницу просмотра на обычной ссылке вида
// .../view?usp=... — gpt-image-2 такое не примет (нужен реальный файл
// картинки). Приводим любую ссылку на Drive-файл к рабочему формату,
// который отдаёт байты картинки напрямую.
function toDirectImageUrl(url) {
  const match = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  if (match) {
    return 'https://lh3.googleusercontent.com/d/' + match[1] + '=s2000';
  }
  return url;
}

// Для 🎨-колонок отдельно: построчно решает, ссылка это или текст —
// ссылки уходят в отдельный список (реальные картинки для художника),
// остальное остаётся текстовой инструкцией.
function collectVisualRefs(tmpl) {
  const textParts = [];
  const urls = [];
  const urlLineRegex = /^https?:\/\/\S+$/;
  for (const key of Object.keys(tmpl)) {
    if (!key.includes('🎨')) continue;
    const value = tmpl[key] || '';
    const lines = value.split('\n').map(l => l.trim()).filter(l => l.length > 0);
    const textLines = [];
    for (const line of lines) {
      if (urlLineRegex.test(line)) { urls.push(toDirectImageUrl(line)); } else { textLines.push(line); }
    }
    if (textLines.length > 0) textParts.push(stripLabel(key) + ':\n' + textLines.join('\n'));
  }
  return { text: textParts.join('\n\n'), urls };
}

const tmpl = $('Находим шаблон канала').first().json;

// Свой раздел SystemPrompt для этапа картинки — только он, не вся ячейка целиком.
const systemPromptKey = Object.keys(tmpl).find(k => k.includes('tmpl_SystemPrompt'));
const pictureRoleNotes = extractSection(tmpl[systemPromptKey], 'КАРТИНКА');

// Остальные 🖋/🎨-колонки (PackagingRules, HashtagPool, TagPool, DalleExamples,
// CharacterPassport, LocationPassports) — как раньше, целиком, они не стадийные.
const sharedKnowledgeText = collectByIcons(tmpl, ['🖋', '🎨']);
const editorKnowledgeText = (pictureRoleNotes ? 'SystemPrompt (этап картинки):\n' + pictureRoleNotes + '\n\n' : '') + sharedKnowledgeText;
const visual = collectVisualRefs(tmpl);

// Первая ссылка в пуле референсов — всегда style guide (по правилу
// таблицы), остальные — обычные референсы локаций/сцен.
const styleGuideUrl = visual.urls[0] || null;
const referenceUrls = visual.urls.slice(1);

return [{
  json: {
    editorKnowledgeText,
    styleGuideUrl,
    referenceUrls,
  }
}];

const photos = $('Вход от диспетчера').first().json.messagePhoto || [];
const largest = photos[photos.length - 1];
return [{ json: { fileId: largest.file_id } }];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const item = $input.first();
const mimeType = (item.binary && item.binary.data && item.binary.data.mimeType) || 'image/jpeg';
const b64 = buffer.toString('base64');
return [{ json: { userImageUrl: `data:${mimeType};base64,${b64}` } }];

const text = $('Вход от диспетчера').first().json.messageText || '';
const urlMatch = text.match(/https?:\/\/\S+/);
if (!urlMatch) return [{ json: { userImageUrl: '' } }];

let url = urlMatch[0];
const driveMatch = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
if (driveMatch) {
  url = 'https://lh3.googleusercontent.com/d/' + driveMatch[1] + '=s2000';
}
return [{ json: { userImageUrl: url } }];

const trigger = $('Вход от диспетчера').first().json;
const project = $('Читаем строку проекта').first().json;
const context = $('Собираем контекст редактора').first().json;

let imageVariants = [];
try { imageVariants = JSON.parse(project.ai_ImageVariants || '[]'); } catch (e) { imageVariants = []; }
if (!Array.isArray(imageVariants)) imageVariants = [];
const variantsSummary = imageVariants.length
  ? imageVariants.map(v => `Вариант ${v.n}: ${(v.dallePrompt || '').slice(0, 200)}`).join('\n')
  : '';

// conversation_id: либо уже был в таблице, либо только что создан
const projectRow = $('Читаем строку проекта').first().json;
let conversationId = projectRow.sys_ConversationId;
try {
  if (!conversationId) {
    conversationId = $('Сохраняем ID разговора').first().json.conversationId;
  }
} catch (e) {}

const editorRole = `Ты — редактор канала "${trigger.sheetName}", соавтор и собеседник автора канала. Сейчас идёт этап КАРТИНКИ: вместе с автором вы проясняете сценку — что происходит, в какой локации, какое настроение, есть ли музыкальная тема. Говори свободно и живо, как обычный человек в разговоре — это не анкета и не чек-лист. Можно шутить, уточнять, предлагать 2-3 конкретных варианта, если у автора нет вдохновения, отвлекаться и возвращаться к теме. Отвечай обычным текстом на русском — никакого JSON, никаких служебных меток внутри текста.

Контекст всего процесса, чтобы ты видела общую картину: выпуск видео проходит через три последовательных этапа — Картинка (это сейчас твой этап), Описание, Техническая часть (заголовок, оверлей, хэштеги, теги, технический подвал с указанием композитора). У каждого этапа свой отдельный собеседник с полным, детальным набором правил именно для своей задачи — когда дойдёт очередь, Писатель получит все инструкции по объёму и стилю описания, а Техническая часть — свои правила по формуле заголовка, оверлею и подвалу. Пока эти этапы ждут своей очереди, тебе не нужно ничего за них додумывать — вся твоя сосредоточенность сейчас на одном: сценка и сама иллюстрация. Так каждый этап получается глубоко проработанным своим специалистом, а не размазанным заранее.

У тебя есть четыре инструмента (function tools), которые ты вызываешь сама, когда решаешь, что момент настал:
- start_drawing — когда сценка полностью прояснена и автор явно, недвусмысленно подтвердил, что готов увидеть картинку. Если сомневаешься, готова ли сценка — лучше спроси ещё раз, чем вызови инструмент раньше времени.
- request_revision — когда автор просит поправить уже нарисованную картинку (и точечная деталь, и кардинальная переделка — один и тот же инструмент, просто по-разному описывай нужное изменение внутри revisionInstruction).
- approve_image — вызывай это в тот самый момент, когда понимаешь, что автор согласовала картинку (сказала «да», «супер», «согласовано» и что угодно в этом духе) — само это понимание и есть повод вызвать инструмент прямо сейчас, а не просто упомянуть в ответе, что согласование зафиксировано.
- update_communication_notes — когда ты сама замечаешь что-то полезное и стоящее того, чтобы запомнить надолго: и про то, как вам удобнее общаться (например: автору нравится, когда ты сама предлагаешь конкретные варианты, а не задаёшь открытые вопросы), и про сами правила канала — если что-то в паспортах, стиле или правилах упаковки показалось неоднозначным и ты для себя решила, как это трактовать, зафиксируй это решение, чтобы не решать каждый раз заново. Вызывай это нечасто, только когда действительно есть чему научиться. В notes всегда передавай ПОЛНЫЙ обновлённый текст заметок — существующие (см. ниже в базе канала) плюс новое наблюдение, — а не только новую строку. Держи заметки короткими и по делу, это живые наблюдения, а не растущий список строгих правил.
Если вместо этого ты замечаешь настоящее противоречие в самих правилах канала (например, две инструкции спорят друг с другом) — не молчи и не решай это тихо сама: скажи об этом прямо в разговоре, как обычной репликой, чтобы автор поправила таблицу.
Если ничего из этого не произошло — просто отвечай текстом, не вызывай инструменты.

Важно про сам dallePrompt для start_drawing: передавай художнику СЫРОЙ МАТЕРИАЛ — факты (например, сам рецепт, конкретные тексты на записках/бумажках, что по сути происходит), короткую идею настроения и локации — а не готовую режиссуру сцены. Не расписывай за него композицию: не указывай, сколько места в кадре занимает персонаж, как разложены элементы, сколько кадров или панелей нужно и что в каждом из них происходит. Это не мелочь — художник в буквальном смысле чувствует пропорции, ритм и раскладку тоньше, чем это можно передать словами, а точные словесные инструкции по композиции ему скорее мешают, чем помогают: он ориентируется на референсы и собственное чутьё, а не на текстовые координаты. Твоя часть работы с автором — прояснить содержание и настроение; сборка самой сцены — целиком его дело.

Отдельно про цвет и общий стиль: референсы (текущая картинка, style guide, дополнительные) задают не только сюжет, но и точную палитру, насыщенность и фактуру — и это первично, важнее любых слов о настроении в самом dallePrompt. Если явно не закрепить в тексте промпта требование держаться референса по цвету, художник может незаметно соскользнуть в более яркую, дефолтную палитру, даже видя референс перед собой. Поэтому в каждом dallePrompt (и для start_drawing, и для request_revision) явно требуй: сохранить ровно ту же сдержанную палитру, свет и фактуру, что на референсе — не ярче, не сочнее. Сначала верность референсу по визуалу, и только затем — сама сценка и действие.

Отдельное правило для гайдов (когда сценка — это пошаговый рецепт или инструкция с текстом прямо на картинке): здесь особенно важно НЕ добавлять от себя ничего сверх сырого рецепта, шагов и референсов — ни придуманные детали интерьера или декора, ни указания по тому, насколько крупным должен быть персонаж или где именно он в кадре. Художник сам прекрасно чувствует этот формат и справляется с ним превосходно без таких инструкций — попытка продиктовать композицию текстом может сломать его собственное чувство ритма и стиля кадра, а не улучшить результат. Единственное, что стоит явно упомянуть в dallePrompt для гайда: весь текст на картинке (ингредиенты, шаги, подписи, tips) должен быть достаточно крупным, чтобы читаться на телефоне без увеличения экрана — не мельчи его; и если рецепт кулинарный, можно напомнить про красивую сервировку в финальном кадре. Дальше — не вмешиваться.

Перед тем как отправить ответ — быстрая самопроверка: если по смыслу твоих же слов картинка уже согласована, готова к рисованию или собеседник попросил правку — а ты ещё не вызвала соответствующий инструмент в этом же ответе — вызови его сейчас, прежде чем отправлять текст. Слова о том, что что-то сделано, без самого вызова — это незавершённое действие, а не выполненное.

Про варианты сцены: start_drawing каждый раз создаёт НОВЫЙ пронумерованный вариант — используешь его, когда нужна другая сценка целиком (не мелкая правка уже нарисованной). request_revision, наоборот, не создаёт новый вариант — он меняет ту же самую картинку, что уже обсуждаете. Если по этому проекту уже есть больше одного варианта, и автор говорит «согласовано» без явного указания номера — переспроси, какой именно вариант она имеет в виду, прежде чем вызывать approve_image. То же самое с правкой: если вариантов несколько, а из разговора не очевидно, какой из них правится (по номеру или по содержанию сцены, которое она описывает) — сначала уточни номер, и передай его в request_revision через variantNumber, не полагайся на то, что это «последний нарисованный» — автор вполне может вернуться поправить более ранний вариант.

${variantsSummary ? 'Уже нарисованные варианты этого проекта:\n' + variantsSummary + '\n\n' : ''}Отдельно про start_drawing: если автор прямо просит начать рисовать («рисуй», «давай», «поехали», «начинай» и подобное) — особенно если это уже не первая такая просьба в этом разговоре — это и есть тот самый явный сигнал готовности. В этот момент вызывай start_drawing сразу в этом же ответе, не задавая новых уточняющих вопросов и не подкидывая ещё идей перед вызовом — если что-то действительно важное для сценки неясно, спрашивай об этом раньше, до того как автор попросит рисовать, а не вместо того, чтобы начать. А вот пока автор сама предлагает варианты, обсуждает детали или просит что-то поискать или уточнить — это по-прежнему обычный разговор без прямой просьбы рисовать, тут инструмент не нужен, продолжай его как обычно.

Вместе с этим сообщением тебе физически показаны настоящие картинки, не просто ссылки на них — можешь и должна смотреть на них прямо сейчас, а не просить их прислать или искать файлы: сначала, если автор только что прислал фото или ссылку прямо в этом сообщении — эта картинка (самая свежая, о ней и идёт речь); затем (если она уже существует) — текущая картинка этого проекта; затем style guide канала; затем, если есть, дополнительные референсы. Это и есть тот самый визуальный материал для консистентности — он уже у тебя перед глазами, отдельно запрашивать его не нужно. Если картинки в этом сообщении нет вообще — значит автор её не присылал, тогда не выдумывай и не говори, что не можешь её открыть, просто продолжай разговор.

База канала (персонаж, локации, стиль, референсы — используй по смыслу подписи каждого блока):
${context.editorKnowledgeText}`;

const userMessage = trigger.messageText;

// Свежая картинка от автора — фото или ссылка, присланные прямо в этом сообщении.
// Сработала ровно одна из двух веток (фото/текст) — читаем ту, что дала результат.
let userImageUrl = '';
try { userImageUrl = $('Кодируем фото в base64').first().json.userImageUrl || ''; } catch (e) {}
if (!userImageUrl) {
  try { userImageUrl = $('Ищем ссылку на изображение в тексте').first().json.userImageUrl || ''; } catch (e) {}
}

return [{
  json: {
    conversationId,
    pendingCallId: projectRow.sys_ConversationId ? (projectRow.sys_PendingToolCallId || '') : '',
    systemPrompt: editorRole,
    userMessage,
    userImageUrl,
    projectId: trigger.projectId,
    chatId: trigger.chatId,
    sheetName: trigger.sheetName,
    channelKey: trigger.channelKey,
    currentDallePrompt: project.ai_DallePromptDraft || '',
    currentImageUrl: project.ai_ImageUrl || '',
    imageVariants,
    styleGuideUrl: context.styleGuideUrl,
    referenceUrls: context.referenceUrls,
  }
}];

const response = $input.first().json;
const output = response.output || [];

// Модель может просто ответить текстом (свободный разговор)...
const messageItem = output.find(item => item.type === 'message');
const textPart = messageItem && (messageItem.content || []).find(c => c.type === 'output_text');
const plainText = textPart ? textPart.text : '';

// ...или вызвать один из настоящих tools — это отдельный тип элемента в output,
// не текст, который нужно парсить регуляркой.
const callItem = output.find(item => item.type === 'function_call');

let action = 'chat';
let messageToUser = plainText;
let dallePrompt = '';
let revisionInstruction = '';
let communicationNotes = '';
let callId = null;
let functionName = null;
let approveVariantNumber = null;
let approveTargetBrightness = null;
let revisionVariantNumber = null;

if (callItem) {
  callId = callItem.call_id;
  functionName = callItem.name;
  let args = {};
  try { args = JSON.parse(callItem.arguments || '{}'); } catch (e) {}
  messageToUser = args.messageToUser || plainText || '';

  if (functionName === 'start_drawing') {
    action = 'ready_to_draw';
    dallePrompt = args.dallePrompt || '';
  } else if (functionName === 'request_revision') {
    action = 'revise_point';
    revisionInstruction = args.revisionInstruction || '';
    revisionVariantNumber = args.variantNumber || null;
  } else if (functionName === 'approve_image') {
    action = 'approved';
    approveVariantNumber = args.variantNumber || null;
    approveTargetBrightness = args.targetBrightness || null;
  } else if (functionName === 'update_communication_notes') {
    // Побочный эффект, не самостоятельное действие — сама реплика остаётся
    // обычным продолжением разговора (action = 'chat'), заметки сохраняются
    // отдельным шагом перед узлом "Куда дальше?".
    communicationNotes = args.notes || '';
  }
}

const prep = $('Готовим запрос редактору').first().json;

// Если согласован конкретный номер варианта — ищем его ссылку среди уже
// нарисованных вариантов; если номер не назван (или вариант всего один),
// откатываемся на текущую/последнюю картинку — как было раньше.
let resolvedApprovedImageUrl = prep.currentImageUrl || '';
if (action === 'approved' && approveVariantNumber && Array.isArray(prep.imageVariants)) {
  const found = prep.imageVariants.find(v => Number(v.n) === Number(approveVariantNumber));
  if (found && found.url) resolvedApprovedImageUrl = found.url;
}

// Правка должна попасть в ТОТ вариант, который редактор назвала (по номеру или
// по смыслу сцены) — а не всегда в последний по счёту, как было раньше (баг:
// просьба поправить более ранний вариант молча правила самый свежий).
let revisionTargetImageUrl = prep.currentImageUrl || '';
let revisionTargetVariantNumber = Array.isArray(prep.imageVariants) && prep.imageVariants.length
  ? prep.imageVariants[prep.imageVariants.length - 1].n
  : 1;
if (action === 'revise_point' && Array.isArray(prep.imageVariants)) {
  const target = revisionVariantNumber
    ? prep.imageVariants.find(v => Number(v.n) === Number(revisionVariantNumber))
    : null;
  if (target && target.url) {
    revisionTargetImageUrl = target.url;
    revisionTargetVariantNumber = target.n;
  }
}

return [{
  json: {
    action,
    messageToUser,
    dallePrompt,
    revisionInstruction,
    communicationNotes,
    callId,
    functionName,
    approveVariantNumber,
    approveTargetBrightness,
    resolvedApprovedImageUrl,
    revisionVariantNumber,
    revisionTargetImageUrl,
    revisionTargetVariantNumber,
    conversationId: prep.conversationId,
    projectId: prep.projectId,
    chatId: prep.chatId,
    sheetName: prep.sheetName,
    channelKey: prep.channelKey,
    currentDallePrompt: prep.currentDallePrompt,
    currentImageUrl: prep.currentImageUrl,
    imageVariants: prep.imageVariants,
    styleGuideUrl: prep.styleGuideUrl,
    referenceUrls: prep.referenceUrls,
  }
}];

// Telegram отклоняет сообщение целиком с ошибкой "message is too long",
// если текст длиннее 4096 символов, — редактор иногда пишет длинные реплики
// (например, целиком описывая несколько вариантов сцены). Режем на несколько
// сообщений подряд вместо того, чтобы ронять всю ветку с ошибкой.
const chatId = $('Парсим ответ редактора').first().json.chatId;
const projectId = $('Парсим ответ редактора').first().json.projectId;
const message = $('Парсим ответ редактора').first().json.messageToUser || '';
const suffix = `\n\nID: ${projectId}`;
const LIMIT = 3900; // с запасом от реального лимита Telegram в 4096

if ((message + suffix).length <= LIMIT) {
  return [{ json: { chatId, text: message + suffix } }];
}

const chunks = [];
let remaining = message;
while (remaining.length > LIMIT) {
  let cut = remaining.lastIndexOf('\n', LIMIT);
  if (cut < LIMIT * 0.5) cut = LIMIT; // нет удобного переноса строки — режем жёстко
  chunks.push(remaining.slice(0, cut));
  remaining = remaining.slice(cut).trimStart();
}
chunks.push(remaining + suffix);

return chunks.map(text => ({ json: { chatId, text } }));

const j = $('Парсим ответ редактора').first().json;
// Style guide всегда первым, затем обычные референсы. Максимум 5 файлов
// на вызов (ограничение API, столько же полей image[] заведено в узле
// рисования) — берём сколько реально есть в таблице, без дублирования
// до полного числа: меньше ссылок — меньше картинок уходит в запрос.
const urls = [j.styleGuideUrl, ...(j.referenceUrls || [])].filter(Boolean).slice(0, 5);

return urls.map((url, i) => ({
  json: { ...j, refUrl: url, refIndex: i }
}));

const binary = {};
for (const item of items) {
  const idx = item.json.refIndex;
  if (item.binary && item.binary.data) {
    binary['image_' + idx] = item.binary.data;
  }
}
const first = items[0] ? items[0].json : {};
return [{
  json: {
    dallePrompt: first.dallePrompt,
    action: first.action,
    projectId: first.projectId,
    chatId: first.chatId,
    sheetName: first.sheetName,
    imageCount: items.length,
  },
  binary
}];

const b64 = items[0].json.data[0].b64_json;
const buffer = Buffer.from(b64, 'base64');
const binary = await this.helpers.prepareBinaryData(buffer, 'scene.png', 'image/png');

return [{
  json: {
    dallePrompt: $('Собираем референсы в один item (B)').first().json.dallePrompt,
    projectId: $('Собираем референсы в один item (B)').first().json.projectId,
    sheetName: $('Собираем референсы в один item (B)').first().json.sheetName,
    chatId: $('Собираем референсы в один item (B)').first().json.chatId,
  },
  binary: { data: binary }
}];

const fileId = $('Загружаем на Диск (B)').first().json.id;
const newUrl = 'https://lh3.googleusercontent.com/d/' + fileId + '=s2000';
const draft = $('Извлекаем картинку (B)').first().json;

// Каждый успешный рисунок через start_drawing — это НОВЫЙ вариант сцены,
// добавляем его в конец списка вариантов, а не перезаписываем единственную
// ячейку (иначе предыдущие варианты терялись бы при каждом новом рисунке).
let variants = [];
try { variants = JSON.parse($('Читаем строку проекта').first().json.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
if (!Array.isArray(variants)) variants = [];
const variantNumber = variants.length + 1;
variants.push({ n: variantNumber, url: newUrl, dallePrompt: draft.dallePrompt });

return [{
  json: {
    sys_ProjectID: draft.projectId,
    ai_ImageUrl: newUrl,
    ai_DallePromptDraft: draft.dallePrompt,
    ai_ImageVariants: JSON.stringify(variants),
    variantNumber,
    sheetName: draft.sheetName,
    chatId: draft.chatId,
  }
}];

// Текущая картинка (image_0) скачана отдельной веткой ещё раньше; здесь
// подмешиваем к ней style guide + референсы (image_1, image_2, ...), собранные
// в предыдущем узле — и считаем итоговое число картинок для правильного
// маршрута на шаге ниже ("Сколько картинок? (C)").
const curItem = $('Скачиваем текущую картинку (C)').first();
const extra = $input.first();

const binary = { image_0: curItem.binary.image_0 };
Object.assign(binary, extra.binary || {});

const imageCount = 1 + (extra.json.extraCount || 0);

return [{
  json: {
    revisionInstruction: extra.json.revisionInstruction,
    projectId: extra.json.projectId,
    chatId: extra.json.chatId,
    sheetName: extra.json.sheetName,
    imageCount,
  },
  binary
}];

const b64 = items[0].json.data[0].b64_json;
const buffer = Buffer.from(b64, 'base64');
const binary = await this.helpers.prepareBinaryData(buffer, 'scene.png', 'image/png');

return [{
  json: {
    projectId: $('Собираем все референсы (C)').first().json.projectId,
    sheetName: $('Собираем все референсы (C)').first().json.sheetName,
    chatId: $('Собираем все референсы (C)').first().json.chatId,
  },
  binary: { data: binary }
}];

const fileId = $('Загружаем на Диск (C)').first().json.id;
const newUrl = 'https://lh3.googleusercontent.com/d/' + fileId + '=s2000';
const draft = $('Извлекаем картинку (C)').first().json;
const parsed = $('Парсим ответ редактора').first().json;

// Правка меняет ссылку у ИМЕННО ТОГО варианта, который был назван (см.
// revisionTargetVariantNumber из "Парсим ответ редактора") — не всегда
// последнего по счёту. Номер варианта не меняется, меняется только картинка.
let variants = [];
try { variants = JSON.parse($('Читаем строку проекта').first().json.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
if (!Array.isArray(variants)) variants = [];

const targetNumber = parsed.revisionTargetVariantNumber || (variants.length ? variants[variants.length - 1].n : 1);
let entry = variants.find(v => Number(v.n) === Number(targetNumber));
if (entry) {
  entry.url = newUrl;
} else {
  entry = { n: targetNumber, url: newUrl, dallePrompt: '' };
  variants.push(entry);
}

// ai_ImageUrl/ai_DallePromptDraft остаются "последним по списку" вариантом —
// как и раньше, это удобный алиас для тех мест кода, которым нужен просто
// один текущий URL (например, форс-согласование или "текущая картинка" для
// свежей правки без явного номера).
const lastVariant = variants[variants.length - 1];

return [{
  json: {
    sys_ProjectID: draft.projectId,
    ai_ImageUrl: lastVariant.url,
    ai_ImageVariants: JSON.stringify(variants),
    variantNumber: entry.n,
    sheetName: draft.sheetName,
    chatId: draft.chatId,
  }
}];

const p = $('Парсим ответ редактора').first().json;
return [{
  json: {
    projectId: p.projectId,
    chatId: p.chatId,
    sheetName: p.sheetName,
    channelKey: p.channelKey,
    messageText: 'Картинка только что согласована — начинай, пожалуйста, обсуждение сцены для описания.',
  }
}];

const req = $('Готовим запрос редактору').first().json;
const parsed = $('Парсим ответ редактора').first().json;

return [{
  json: {
    classifierInput: `Автор написал: "${req.userMessage}"\n\nРедактор ответил: "${parsed.messageToUser}"`,
  }
}];

const response = $input.first().json;
const output = response.output || [];
const messageItem = output.find(i => i.type === 'message');
const textPart = messageItem && (messageItem.content || []).find(c => c.type === 'output_text');
const raw = (textPart ? textPart.text : '').trim().toLowerCase();
const isApproved = raw.startsWith('true');

const parsed = $('Парсим ответ редактора').first().json;
return [{ json: { ...parsed, isApproved } }];

const p = $('Разбираем классификатор').first().json;
return [{
  json: {
    projectId: p.projectId,
    chatId: p.chatId,
    sheetName: p.sheetName,
    channelKey: p.channelKey,
    messageText: 'Картинка только что согласована — начинай, пожалуйста, обсуждение сцены для описания.',
  }
}];

