const parsed = $('Парсим ответ редактора').first().json;
// Style guide + до 5 референсов — столько, сколько реально есть, без
// дублирования до фиксированного числа (тот же принцип, что и при первом
// рисовании): мало ссылок — меньше картинок уйдёт художнику на правку.
